fn bool_setting_command_for(key: &'static str, value: bool) -> Command {
    Command::SetSetting {
        key: SmolStr::new_static(key),
        value: bento_nano_app::SettingValue::Bool(value),
    }
}

fn next_encryption_mode(current: SettingsEncryptionMode) -> SettingsEncryptionMode {
    match current {
        SettingsEncryptionMode::None => SettingsEncryptionMode::Dpapi,
        SettingsEncryptionMode::Dpapi => SettingsEncryptionMode::None,
        SettingsEncryptionMode::Passphrase => SettingsEncryptionMode::None,
    }
}

fn next_update_frequency(current: UpdateCheckFrequency) -> UpdateCheckFrequency {
    match current {
        UpdateCheckFrequency::Daily => UpdateCheckFrequency::Weekly,
        UpdateCheckFrequency::Weekly => UpdateCheckFrequency::Manual,
        UpdateCheckFrequency::Manual => UpdateCheckFrequency::Daily,
    }
}

fn should_start_background_update_check(frequency: UpdateCheckFrequency) -> bool {
    update_check_interval(frequency).is_some()
}

fn update_check_interval(frequency: UpdateCheckFrequency) -> Option<std::time::Duration> {
    bento_nano_backend::updater::check_interval_hours(frequency)
        .map(|hours| std::time::Duration::from_secs(hours.saturating_mul(60 * 60)))
}

fn maybe_start_background_update_check(root: &AppRoot) {
    let frequency = root.app.borrow().update_check_frequency.get();
    if !should_start_background_update_check(frequency) {
        return;
    }
    if let Some(interval) = update_check_interval(frequency) {
        root.updater.spawn_recurring_background_check(interval);
    }
}

fn encryption_mode_from_wire(value: &str) -> Option<SettingsEncryptionMode> {
    match value {
        "None" => Some(SettingsEncryptionMode::None),
        "Dpapi" => Some(SettingsEncryptionMode::Dpapi),
        "Passphrase" => Some(SettingsEncryptionMode::Passphrase),
        _ => None,
    }
}

fn backend_encryption_mode_from_app(
    mode: SettingsEncryptionMode,
) -> bento_nano_backend::config_vault::EncryptionMode {
    match mode {
        SettingsEncryptionMode::None => bento_nano_backend::config_vault::EncryptionMode::None,
        SettingsEncryptionMode::Dpapi => bento_nano_backend::config_vault::EncryptionMode::Dpapi,
        SettingsEncryptionMode::Passphrase => {
            bento_nano_backend::config_vault::EncryptionMode::None
        }
    }
}

fn update_frequency_wire(frequency: UpdateCheckFrequency) -> &'static str {
    match frequency {
        UpdateCheckFrequency::Daily => "Daily",
        UpdateCheckFrequency::Weekly => "Weekly",
        UpdateCheckFrequency::Manual => "Manual",
    }
}

fn update_frequency_from_wire(value: &str) -> Option<UpdateCheckFrequency> {
    match value {
        "Daily" => Some(UpdateCheckFrequency::Daily),
        "Weekly" => Some(UpdateCheckFrequency::Weekly),
        "Manual" => Some(UpdateCheckFrequency::Manual),
        _ => None,
    }
}

fn theme_base_accent_from_wire(value: &str) -> Option<SmolStr> {
    palette_picker::swatch_table()
        .iter()
        .find(|swatch| swatch.hex.as_str() == value)
        .map(|swatch| swatch.hex.clone())
}

fn apply_theme_base_accent_to_app(app: &AppState, accent: Option<SmolStr>) -> bool {
    let mut current = app.theme_base_accent.borrow_mut();
    if *current == accent {
        return false;
    }
    *current = accent;
    true
}

fn persist_theme_base_accent_to_vault(
    vault: &mut bento_nano_backend::config_vault::Vault,
    accent: Option<&SmolStr>,
) -> Result<bool, bento_nano_backend::config_vault::VaultError> {
    if vault.is_locked_passphrase() {
        return Err(bento_nano_backend::config_vault::VaultError::NoPassphraseSet);
    }
    match accent {
        Some(hex) => {
            if theme_base_accent_from_wire(hex.as_str()).is_none() {
                tracing::warn!(
                    target: "bentodesk::vault",
                    %hex,
                    "theme.base_accent rejected: unsupported palette swatch"
                );
                return Ok(false);
            }
            vault.set_setting(
                SETTING_THEME_BASE_ACCENT,
                bento_nano_backend::config_vault::SettingValue::Str(hex.clone()),
            );
        }
        None => {
            vault.remove_setting(SETTING_THEME_BASE_ACCENT);
        }
    }
    vault.flush()?;
    Ok(true)
}

fn themes_dir_for_root(root: &AppRoot) -> PathBuf {
    themes::themes_dir(&state_dir_for_root(root))
}

fn state_dir_for_root(root: &AppRoot) -> PathBuf {
    let zones_path = root.app.borrow().zones_path.clone();
    if let Some(parent) = zones_path
        .parent()
        .filter(|_| !zones_path.as_os_str().is_empty())
    {
        return parent.to_path_buf();
    }
    match storage::appdata_path() {
        Ok(path) => path
            .parent()
            .map(Path::to_path_buf)
            .unwrap_or_else(|| PathBuf::from(".")),
        Err(_error) => PathBuf::from("."),
    }
}

fn migrate_legacy_tauri_settings_to_vault(state_dir: &Path) {
    let accepted_accents = palette_picker::swatch_table()
        .iter()
        .map(|swatch| swatch.hex.as_str())
        .collect::<smallvec::SmallVec<[&str; 16]>>();
    let Some(mtx) = bento_nano_backend::config_vault::Vault::global() else {
        return;
    };
    let Ok(mut vault) = mtx.lock() else {
        tracing::warn!(
            target: "bentodesk::vault",
            "legacy Tauri settings import skipped: vault mutex poisoned"
        );
        return;
    };
    match bento_nano_backend::config_vault::tauri_settings::migrate_first_existing_tauri_settings(
        state_dir,
        &mut vault,
        &accepted_accents,
    ) {
        Ok(report) if report.vault_locked => {
            tracing::warn!(
                target: "bentodesk::vault",
                source = ?report.source_path,
                "legacy Tauri settings import skipped: passphrase vault locked"
            );
        }
        Ok(report) if report.imported_any() => {
            tracing::info!(
                target: "bentodesk::vault",
                source = ?report.source_path,
                imported = ?report.imported_keys,
                skipped_existing = ?report.skipped_existing_keys,
                skipped_invalid = ?report.skipped_invalid_fields,
                skipped_unsupported = ?report.skipped_unsupported_fields,
                "legacy Tauri settings imported into selected-stack vault"
            );
        }
        Ok(report) if report.only_skipped_existing() => {
            tracing::debug!(
                target: "bentodesk::vault",
                source = ?report.source_path,
                skipped_existing = ?report.skipped_existing_keys,
                "legacy Tauri settings import found no missing vault keys"
            );
        }
        Ok(report) => {
            if report.source_path.is_some()
                && (!report.skipped_invalid_fields.is_empty()
                    || !report.skipped_unsupported_fields.is_empty())
            {
                tracing::warn!(
                    target: "bentodesk::vault",
                    source = ?report.source_path,
                    skipped_invalid = ?report.skipped_invalid_fields,
                    skipped_unsupported = ?report.skipped_unsupported_fields,
                    "legacy Tauri settings import completed with skipped fields"
                );
            }
        }
        Err(error) => {
            tracing::warn!(
                target: "bentodesk::vault",
                error = %error,
                "legacy Tauri settings import failed; selected-stack vault remains authoritative"
            );
        }
    }
}

fn theme_options_from_themes(themes: &[bento_nano_backend::themes::Theme]) -> Vec<ThemeOption> {
    themes
        .iter()
        .map(|theme| ThemeOption {
            id: theme.id.clone(),
            name: theme.name.clone(),
            is_builtin: theme.is_builtin,
        })
        .collect()
}

fn load_themes_for_root(
    root: &AppRoot,
) -> Result<Vec<bento_nano_backend::themes::Theme>, ThemeError> {
    themes::load_all_themes(&themes_dir_for_root(root))
}

fn import_theme_for_root(
    root: &AppRoot,
    source_path: &Path,
) -> Result<bento_nano_backend::themes::Theme, ThemeError> {
    themes::import_theme_file(source_path, &themes_dir_for_root(root))
}

fn load_available_theme_options(root: &AppRoot) -> Result<Vec<ThemeOption>, ThemeError> {
    load_themes_for_root(root).map(|loaded| theme_options_from_themes(&loaded))
}

fn apply_available_themes_to_app(root: &AppRoot) -> Result<bool, ThemeError> {
    let options = load_available_theme_options(root)?;
    let app = root.app.borrow();
    Ok(app.set_available_themes(options))
}

fn plugin_type_label(plugin_type: &PluginType) -> SmolStr {
    match plugin_type {
        PluginType::Theme => SmolStr::new_static("theme"),
        PluginType::Widget => SmolStr::new_static("widget"),
        PluginType::Organizer => SmolStr::new_static("organizer"),
    }
}

fn plugin_entries_from_registry(registry: PluginRegistry) -> Vec<SettingsPluginEntry> {
    registry
        .plugins
        .into_iter()
        .map(|plugin| SettingsPluginEntry {
            id: SmolStr::new(plugin.id),
            name: SmolStr::new(plugin.name),
            version: SmolStr::new(plugin.version),
            plugin_type: plugin_type_label(&plugin.plugin_type),
            // M1h — thread the manifest author/description (already loaded by
            // the registry) through so the inline §11 plugin card shows the
            // author + description lines (Tauri `plugin-card__author/__desc`).
            author: SmolStr::new(plugin.author),
            description: SmolStr::new(plugin.description),
            enabled: plugin.enabled,
        })
        .collect()
}

fn list_plugins_for_root(root: &AppRoot) -> Result<Vec<SettingsPluginEntry>, String> {
    PluginRegistry::load(&state_dir_for_root(root))
        .map(plugin_entries_from_registry)
        .map_err(|error| error.to_string())
}

fn refresh_settings_plugins_for_root(root: &AppRoot) -> Result<bool, String> {
    let entries = list_plugins_for_root(root)?;
    let app = root.app.borrow();
    Ok(app.set_settings_plugins(entries))
}

fn apply_theme_after_plugin_mutation(root: &AppRoot) -> Result<bool, String> {
    let current_id = {
        let app = root.app.borrow();
        app.active_theme_id.borrow().clone()
    };
    let loaded = load_themes_for_root(root).map_err(|error| error.to_string())?;
    let options = theme_options_from_themes(&loaded);
    let theme = loaded
        .iter()
        .find(|theme| theme.id == current_id)
        .or_else(|| loaded.iter().find(|theme| theme.is_builtin))
        .cloned()
        .ok_or_else(|| "No themes available after plugin mutation".to_owned())?;
    if theme.id != current_id {
        if let Some(mtx) = bento_nano_backend::config_vault::Vault::global() {
            if let Ok(mut vault) = mtx.lock() {
                let _ = persist_active_theme_to_vault(&mut vault, &theme.id);
            }
        }
    }
    apply_active_theme_selection_to_app(root, options, theme).map_err(|error| error.to_string())
}

fn refresh_plugin_dependent_state(root: &AppRoot) -> Result<bool, String> {
    let mut changed = refresh_settings_plugins_for_root(root)?;
    changed |= apply_theme_after_plugin_mutation(root)?;
    Ok(changed)
}

fn set_plugin_setting_error(root: &AppRoot, message: SmolStr) {
    let app = root.app.borrow();
    app.settings_plugin_status
        .borrow_mut()
        .replace(SettingsBackupStatus::Error(message));
}

fn set_plugin_setting_success(root: &AppRoot, message: SmolStr) {
    let app = root.app.borrow();
    app.settings_plugin_status
        .borrow_mut()
        .replace(SettingsBackupStatus::Success(message));
}

fn load_theme_selection_for_root(
    root: &AppRoot,
    id: &str,
) -> Result<(Vec<ThemeOption>, bento_nano_backend::themes::Theme), ThemeError> {
    let loaded = load_themes_for_root(root)?;
    let options = theme_options_from_themes(&loaded);
    let Some(theme) = loaded.into_iter().find(|theme| theme.id.as_str() == id) else {
        return Err(ThemeError::NotFound { id: id.to_owned() });
    };
    Ok((options, theme))
}

fn apply_active_theme_selection_to_app(
    root: &AppRoot,
    options: Vec<ThemeOption>,
    theme: bento_nano_backend::themes::Theme,
) -> Result<bool, ThemeError> {
    let tokens = themes::to_theme_tokens(&theme)?;
    let app = root.app.borrow();
    let mut changed = app.set_available_themes(options);
    changed |= app.apply_active_theme(theme.id.clone(), theme.name.clone(), tokens);
    app.settings_theme_status
        .borrow_mut()
        .replace(SettingsBackupStatus::Success(SmolStr::new(format!(
            "Theme {}",
            theme.name
        ))));
    Ok(changed)
}

fn apply_active_theme_to_app(root: &AppRoot, id: SmolStr) -> Result<bool, ThemeError> {
    let (options, theme) = load_theme_selection_for_root(root, id.as_str())?;
    apply_active_theme_selection_to_app(root, options, theme)
}

fn persist_active_theme_to_vault(
    vault: &mut bento_nano_backend::config_vault::Vault,
    id: &SmolStr,
) -> Result<bool, bento_nano_backend::config_vault::VaultError> {
    if vault.is_locked_passphrase() {
        return Err(bento_nano_backend::config_vault::VaultError::NoPassphraseSet);
    }
    vault.set_setting(
        SETTING_ACTIVE_THEME,
        bento_nano_backend::config_vault::SettingValue::Str(id.clone()),
    );
    vault.flush()?;
    Ok(true)
}

