fn collect_context_capsule_candidates(
    zones_path: &Path,
) -> Result<Vec<ContextCapsuleCandidate>, ContextCapsuleError> {
    let capsule_dir = context_capsule_dir_for_zones_path(zones_path)?;
    if !capsule_dir.exists() {
        return Ok(Vec::new());
    }
    let mut candidates = Vec::new();
    let read_dir = std::fs::read_dir(&capsule_dir).map_err(|source| ContextCapsuleError::Io {
        op: "read capsule dir",
        path: capsule_dir.clone(),
        source,
    })?;
    for item in read_dir {
        let dir_entry = item.map_err(|source| ContextCapsuleError::Io {
            op: "read capsule dir entry",
            path: capsule_dir.clone(),
            source,
        })?;
        let path = dir_entry.path();
        let Some(file_name) = path.file_name().and_then(|value| value.to_str()) else {
            continue;
        };
        let Some(capsule_id) = context_capsule_id_from_file_name(file_name) else {
            continue;
        };
        let capsule_id = SmolStr::new(capsule_id);
        let metadata = dir_entry
            .metadata()
            .map_err(|source| ContextCapsuleError::Io {
                op: "read capsule metadata",
                path: path.clone(),
                source,
            })?;
        if !metadata.is_file() {
            continue;
        }
        let modified = metadata.modified().unwrap_or(UNIX_EPOCH);
        let entry = match std::fs::read(&path) {
            Ok(payload) => envelope_entry_from_payload(capsule_id.clone(), modified, &payload),
            Err(_) => CapsuleEntry::new(
                capsule_id.clone(),
                display_name_from_context_capsule_id(capsule_id.as_str()),
                "archive",
                bento_nano_backend::time::system_time_to_rfc3339(modified),
            ),
        };
        candidates.push(ContextCapsuleCandidate {
            path,
            entry,
            modified,
        });
    }
    candidates.sort_by(|left, right| right.modified.cmp(&left.modified));
    Ok(candidates)
}

fn list_context_capsules_for_path(
    zones_path: &Path,
) -> Result<smallvec::SmallVec<[CapsuleEntry; 8]>, ContextCapsuleError> {
    let mut entries = smallvec::SmallVec::new();
    for candidate in collect_context_capsule_candidates(zones_path)?
        .into_iter()
        .take(32)
    {
        entries.push(candidate.entry);
    }
    Ok(entries)
}

fn find_context_capsule_file_by_id(
    zones_path: &Path,
    capsule_id: &str,
) -> Result<PathBuf, ContextCapsuleError> {
    if capsule_id.trim().is_empty() {
        return Err(ContextCapsuleError::EmptyCapsuleId);
    }
    let candidates = collect_context_capsule_candidates(zones_path)?;
    candidates
        .into_iter()
        .find(|candidate| candidate.entry.id.as_str() == capsule_id)
        .map(|candidate| candidate.path)
        .ok_or_else(|| ContextCapsuleError::CapsuleNotFound(SmolStr::new(capsule_id)))
}

fn capture_context_capsule_for_path(
    zones_path: &Path,
    zones: &ZoneList,
    name: &str,
) -> Result<CapsuleEntry, ContextCapsuleError> {
    let capsule_dir = context_capsule_dir_for_zones_path(zones_path)?;
    std::fs::create_dir_all(&capsule_dir).map_err(|source| ContextCapsuleError::Io {
        op: "create capsule dir",
        path: capsule_dir.clone(),
        source,
    })?;
    let capsule_id = new_context_capsule_id(name);
    let capsule_path = capsule_dir.join(context_capsule_file_name(capsule_id.as_str()));
    let temp_path = capsule_dir.join(format!("{capsule_id}.tmp"));
    let payload = encode_context_capsule_envelope(zones, name, capture_live_context_windows())?;
    std::fs::write(&temp_path, payload).map_err(|source| ContextCapsuleError::Io {
        op: "write capsule temp file",
        path: temp_path.clone(),
        source,
    })?;
    if let Err(source) = std::fs::rename(&temp_path, &capsule_path) {
        let _ = std::fs::remove_file(&temp_path);
        return Err(ContextCapsuleError::Io {
            op: "promote capsule file",
            path: capsule_path,
            source,
        });
    }
    Ok(CapsuleEntry::new(
        capsule_id.clone(),
        SmolStr::new(name.trim()),
        "briefcase",
        bento_nano_backend::time::now_rfc3339(),
    ))
}

fn restore_context_capsule_for_path(
    zones_path: &Path,
    capsule_id: &str,
) -> Result<ZoneList, ContextCapsuleError> {
    let capsule_path = find_context_capsule_file_by_id(zones_path, capsule_id)?;
    let payload = std::fs::read(&capsule_path).map_err(|source| ContextCapsuleError::Io {
        op: "read capsule file",
        path: capsule_path.clone(),
        source,
    })?;
    decode_context_capsule_zones(&payload)
}

fn delete_context_capsule_for_path(
    zones_path: &Path,
    capsule_id: &str,
) -> Result<(), ContextCapsuleError> {
    let capsule_path = find_context_capsule_file_by_id(zones_path, capsule_id)?;
    std::fs::remove_file(&capsule_path).map_err(|source| ContextCapsuleError::Io {
        op: "delete capsule file",
        path: capsule_path,
        source,
    })
}

fn refresh_context_capsule_picker(root: &AppRoot) -> Result<(), ContextCapsuleError> {
    let zones_path = root.app.borrow().zones_path.clone();
    let entries = list_context_capsules_for_path(&zones_path)?;
    let app = root.app.borrow();
    let mut picker = app.capsule_picker.borrow_mut();
    picker.set_entries(entries);
    picker.set_busy(false);
    picker.set_error(None);
    Ok(())
}

fn capture_context_capsule(
    root: &AppRoot,
    name: &str,
) -> Result<CapsuleEntry, ContextCapsuleError> {
    let (zones_path, zones) = {
        let app = root.app.borrow();
        (app.zones_path.clone(), app.zones.clone())
    };
    let entry = capture_context_capsule_for_path(&zones_path, &zones, name)?;
    refresh_context_capsule_picker(root)?;
    Ok(entry)
}

fn restore_context_capsule(root: &AppRoot, capsule_id: &str) -> Result<usize, ContextCapsuleError> {
    let zones_path = root.app.borrow().zones_path.clone();
    let zones = restore_context_capsule_for_path(&zones_path, capsule_id)?;
    let restored_count = zones.len();
    {
        let mut app = root.app.borrow_mut();
        app.zones = zones;
        app.mark_dirty();
    }
    refresh_context_capsule_picker(root)?;
    Ok(restored_count)
}

fn delete_context_capsule(root: &AppRoot, capsule_id: &str) -> Result<(), ContextCapsuleError> {
    let zones_path = root.app.borrow().zones_path.clone();
    delete_context_capsule_for_path(&zones_path, capsule_id)?;
    refresh_context_capsule_picker(root)
}

#[derive(Debug)]
enum TimelineError {
    MissingStateDir,
    EmptyCheckpointId,
    CheckpointNotFound(SmolStr),
    Checkpoint(CheckpointError),
}

impl core::fmt::Display for TimelineError {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        match self {
            Self::MissingStateDir => f.write_str("timeline state directory is unavailable"),
            Self::EmptyCheckpointId => f.write_str("checkpoint id is empty"),
            Self::CheckpointNotFound(id) => write!(f, "checkpoint not found: {id}"),
            Self::Checkpoint(source) => write!(f, "checkpoint store failed: {source}"),
        }
    }
}

impl core::error::Error for TimelineError {}

impl From<CheckpointError> for TimelineError {
    fn from(value: CheckpointError) -> Self {
        Self::Checkpoint(value)
    }
}

#[derive(Debug)]
enum SnapshotPickerError {
    MissingStateDir,
    EmptySnapshotId,
    SnapshotNotFound(SmolStr),
    Layout(LayoutError),
}

impl core::fmt::Display for SnapshotPickerError {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        match self {
            Self::MissingStateDir => f.write_str("snapshot state directory is unavailable"),
            Self::EmptySnapshotId => f.write_str("snapshot id is empty"),
            Self::SnapshotNotFound(id) => write!(f, "snapshot not found: {id}"),
            Self::Layout(source) => write!(f, "snapshot store failed: {source}"),
        }
    }
}

impl core::error::Error for SnapshotPickerError {}

impl From<LayoutError> for SnapshotPickerError {
    fn from(value: LayoutError) -> Self {
        Self::Layout(value)
    }
}

fn timeline_dir_for_zones_path(zones_path: &Path) -> Result<PathBuf, TimelineError> {
    let Some(parent) = zones_path.parent() else {
        return Err(TimelineError::MissingStateDir);
    };
    Ok(parent.join("timeline"))
}

fn snapshot_dir_for_zones_path(zones_path: &Path) -> Result<PathBuf, SnapshotPickerError> {
    let Some(parent) = zones_path.parent() else {
        return Err(SnapshotPickerError::MissingStateDir);
    };
    Ok(parent.join("snapshots"))
}

fn current_snapshot_manager(root: &AppRoot) -> Result<SnapshotManager, SnapshotPickerError> {
    let zones_path = root.app.borrow().zones_path.clone();
    if !zones_path.as_os_str().is_empty() {
        return Ok(SnapshotManager::new(snapshot_dir_for_zones_path(
            &zones_path,
        )?));
    }
    let fallback = storage::appdata_path().map_err(|_| SnapshotPickerError::MissingStateDir)?;
    Ok(SnapshotManager::new(snapshot_dir_for_zones_path(
        &fallback,
    )?))
}

fn current_timeline_store(root: &AppRoot) -> Result<CheckpointStore, TimelineError> {
    let zones_path = root.app.borrow().zones_path.clone();
    if !zones_path.as_os_str().is_empty() {
        return Ok(CheckpointStore::new(timeline_dir_for_zones_path(
            &zones_path,
        )?));
    }
    let fallback = storage::appdata_path().map_err(|_| TimelineError::MissingStateDir)?;
    Ok(CheckpointStore::new(timeline_dir_for_zones_path(
        &fallback,
    )?))
}

