unsafe fn select_file_from_dialog(
    owner: HWND,
    filter_text: &str,
    title_text: &str,
    default_extension_text: &str,
    failure_label: &str,
) -> Result<Option<PathBuf>, String> {
    const MAX_FILE_PATH_U16: usize = 4096;
    const MAX_FILE_PATH_U32: u32 = 4096;

    let filter = widen_dynamic(filter_text);
    let title = widen_dynamic(title_text);
    let default_extension = widen_dynamic(default_extension_text);
    let mut file_buffer = [0u16; MAX_FILE_PATH_U16];
    // SAFETY: OPENFILENAMEW is a plain C struct. We fill every field required
    // by GetOpenFileNameW before passing its mutable pointer to comdlg32.
    let mut dialog = unsafe { core::mem::zeroed::<OPENFILENAMEW>() };
    dialog.lStructSize = core::mem::size_of::<OPENFILENAMEW>() as u32;
    dialog.hwndOwner = owner;
    dialog.lpstrFilter = filter.as_ptr();
    dialog.lpstrFile = file_buffer.as_mut_ptr();
    dialog.nMaxFile = MAX_FILE_PATH_U32;
    dialog.lpstrTitle = title.as_ptr();
    dialog.lpstrDefExt = default_extension.as_ptr();
    dialog.Flags = OFN_EXPLORER | OFN_FILEMUSTEXIST | OFN_HIDEREADONLY | OFN_PATHMUSTEXIST;

    // SAFETY: dialog points to a live OPENFILENAMEW; string buffers remain
    // alive for the duration of the modal call; lpstrFile is writable.
    let accepted = unsafe { GetOpenFileNameW(&mut dialog) };
    if accepted == 0 {
        // SAFETY: CommDlgExtendedError is the documented way to distinguish
        // cancellation from a common-dialog failure after GetOpenFileNameW.
        let error = unsafe { CommDlgExtendedError() };
        if error == 0 {
            return Ok(None);
        }
        return Err(format!(
            "native {failure_label} picker failed: 0x{error:08X}"
        ));
    }

    let len = file_buffer
        .iter()
        .position(|unit| *unit == 0)
        .unwrap_or(file_buffer.len());
    let path = String::from_utf16_lossy(&file_buffer[..len]);
    let path = path.trim();
    if path.is_empty() {
        return Err(format!(
            "native {failure_label} picker returned an empty file path"
        ));
    }
    Ok(Some(PathBuf::from(path)))
}

fn bind_zone_to_folder(root: &AppRoot, zone_id: ZoneId, folder: &str) -> Result<bool, String> {
    let folder = PathBuf::from(folder.trim());
    if root.app.borrow().zones.get(zone_id).is_none() {
        return Err(format!("live folder zone not found: {}", zone_id.0));
    }
    bento_nano_backend::watcher::bind(zone_id, &folder).map_err(|error| error.to_string())?;
    let changed = {
        let mut app = root.app.borrow_mut();
        let Some(zone) = app.zones.get_mut(zone_id) else {
            let _ = bento_nano_backend::watcher::unbind(zone_id);
            return Err(format!("live folder zone not found: {}", zone_id.0));
        };
        zone.set_live_folder_path(Some(Cow::Owned(folder.to_string_lossy().to_string())))
    };
    if changed {
        root.app.borrow().mark_dirty();
    }
    let refreshed = refresh_live_folder_zone(root, zone_id)?;
    let item_count = root
        .app
        .borrow()
        .zones
        .get(zone_id)
        .map(|zone| zone.items.len())
        .unwrap_or(0);
    root.app
        .borrow()
        .rules_wizard_status
        .borrow_mut()
        .replace(SmolStr::new(format!(
            "Live folder bound zone {} to {}; items={item_count}",
            zone_id.0,
            folder.display()
        )));
    Ok(changed || refreshed)
}

fn unbind_zone_folder(root: &AppRoot, zone_id: ZoneId) -> Result<bool, String> {
    bento_nano_backend::watcher::unbind(zone_id).map_err(|error| error.to_string())?;
    let mut app = root.app.borrow_mut();
    let Some(zone) = app.zones.get_mut(zone_id) else {
        return Err(format!("live folder zone not found: {}", zone_id.0));
    };
    let changed = zone.set_live_folder_path(None) || !zone.items.is_empty();
    if changed {
        zone.items.clear();
        app.mark_dirty();
    }
    app.rules_wizard_status
        .borrow_mut()
        .replace(SmolStr::new(format!(
            "Live folder unbound from zone {}",
            zone_id.0
        )));
    Ok(changed)
}

fn rehydrate_live_folder_bindings(root: &AppRoot) -> bool {
    rehydrate_live_folder_bindings_with(
        root,
        |zone_id, folder| {
            bento_nano_backend::watcher::bind(zone_id, folder).map_err(|error| error.to_string())
        },
        refresh_live_folder_zone,
    )
}

fn rehydrate_live_folder_bindings_with<Bind, Refresh>(
    root: &AppRoot,
    mut bind: Bind,
    mut refresh: Refresh,
) -> bool
where
    Bind: FnMut(ZoneId, &Path) -> Result<(), String>,
    Refresh: FnMut(&AppRoot, ZoneId) -> Result<bool, String>,
{
    if root.live_folder_rehydrated.replace(true) {
        return false;
    }
    let bindings = {
        let app = root.app.borrow();
        app.zones
            .iter()
            .filter_map(|zone| {
                zone.live_folder_path
                    .as_deref()
                    .map(|folder| (zone.id, PathBuf::from(folder)))
            })
            .collect::<Vec<_>>()
    };

    let mut changed = false;
    for (zone_id, folder) in bindings {
        match bind(zone_id, &folder).and_then(|_| refresh(root, zone_id)) {
            Ok(zone_changed) => changed |= zone_changed,
            Err(error) => {
                tracing::warn!(
                    target: "bentodesk::live_folder",
                    zone_id = zone_id.0,
                    folder = %folder.display(),
                    error = %error,
                    "live folder rehydrate failed"
                );
                set_live_folder_error(
                    root,
                    format!(
                        "Live folder rehydrate failed for zone {}: {error}",
                        zone_id.0
                    ),
                );
                changed = true;
            }
        }
    }
    changed
}

#[derive(Debug)]
enum RulesWizardError {
    MissingStateDir,
    NoDesktopSource,
    RuleNotFound(SmolStr),
    Platform(PlatformError),
    Persistence(rules::RulesError),
    Preview(String),
    Execution(String),
}

impl core::fmt::Display for RulesWizardError {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        match self {
            Self::MissingStateDir => f.write_str("rules state directory is unavailable"),
            Self::NoDesktopSource => f.write_str("no desktop source is available for preview"),
            Self::RuleNotFound(id) => write!(f, "rule not found: {id}"),
            Self::Platform(source) => write!(f, "platform storage failed: {source}"),
            Self::Persistence(source) => write!(f, "rules persistence failed: {source}"),
            Self::Preview(source) => write!(f, "rules preview failed: {source}"),
            Self::Execution(source) => write!(f, "rules execution failed: {source}"),
        }
    }
}

impl core::error::Error for RulesWizardError {}

impl From<PlatformError> for RulesWizardError {
    fn from(value: PlatformError) -> Self {
        Self::Platform(value)
    }
}

impl From<rules::RulesError> for RulesWizardError {
    fn from(value: rules::RulesError) -> Self {
        Self::Persistence(value)
    }
}

fn rules_state_dir_for_zones_path(zones_path: &Path) -> Result<PathBuf, RulesWizardError> {
    let Some(parent) = zones_path.parent() else {
        return Err(RulesWizardError::MissingStateDir);
    };
    Ok(parent.to_path_buf())
}

fn current_rules_state_dir(root: &AppRoot) -> Result<PathBuf, RulesWizardError> {
    let zones_path = root.app.borrow().zones_path.clone();
    if !zones_path.as_os_str().is_empty() {
        return rules_state_dir_for_zones_path(&zones_path);
    }
    let fallback = storage::appdata_path()?;
    rules_state_dir_for_zones_path(&fallback)
}

fn new_rule_id() -> SmolStr {
    let stamp = bento_nano_backend::time::now_compact_rfc3339();
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_or(0, |duration| duration.subsec_nanos());
    SmolStr::new(format!("rule-{stamp}-{:x}-{nanos:08x}", std::process::id()))
}

fn stamp_rule_id_if_empty(mut rule: Rule) -> Rule {
    if rule.id.as_str().trim().is_empty() {
        rule.id = new_rule_id();
    }
    rule
}

fn save_rule_for_state_dir(state_dir: &Path, rule: Rule) -> Result<Rule, RulesWizardError> {
    let rule = stamp_rule_id_if_empty(rule);
    rules::upsert(state_dir, rule.clone())?;
    Ok(rule)
}

fn delete_rule_for_state_dir(state_dir: &Path, rule_id: &str) -> Result<(), RulesWizardError> {
    rules::delete(state_dir, rule_id)?;
    Ok(())
}

fn refresh_rules_wizard(root: &AppRoot) -> Result<usize, RulesWizardError> {
    let state_dir = current_rules_state_dir(root)?;
    let rules = rules::load_all(&state_dir);
    let count = rules.len();
    let app = root.app.borrow();
    *app.rules_wizard_rules.borrow_mut() = rules;
    app.rules_wizard_delete_confirm.borrow_mut().take();
    if count == 0 {
        app.rules_wizard_rule_cursor.set(0);
    } else {
        let cursor = app.rules_wizard_rule_cursor.get().min(count - 1);
        app.rules_wizard_rule_cursor.set(cursor);
    }
    app.rules_wizard_status
        .borrow_mut()
        .replace(SmolStr::new(format!("Loaded {count} persisted rules")));
    Ok(count)
}

fn persist_rule_for_wizard(root: &AppRoot, rule: Rule) -> Result<(), RulesWizardError> {
    let state_dir = current_rules_state_dir(root)?;
    let saved = save_rule_for_state_dir(&state_dir, rule)?;
    let count = refresh_rules_wizard(root)?;
    let app = root.app.borrow();
    app.rules_wizard.borrow_mut().load_rule(saved.clone());
    app.rules_wizard.borrow_mut().set_error(None);
    app.rules_wizard_status
        .borrow_mut()
        .replace(SmolStr::new(format!(
            "Saved rule '{}' ({count} total)",
            saved.name
        )));
    Ok(())
}

fn delete_rule_for_wizard(root: &AppRoot, rule_id: &str) -> Result<(), RulesWizardError> {
    let state_dir = current_rules_state_dir(root)?;
    delete_rule_for_state_dir(&state_dir, rule_id)?;
    let count = refresh_rules_wizard(root)?;
    let app = root.app.borrow();
    app.rules_wizard.borrow_mut().set_error(None);
    app.rules_wizard_status
        .borrow_mut()
        .replace(SmolStr::new(format!(
            "Deleted rule {rule_id} ({count} total)"
        )));
    Ok(())
}

fn set_rules_wizard_error(root: &AppRoot, message: SmolStr) {
    let app = root.app.borrow();
    app.rules_wizard.borrow_mut().set_error(Some(message));
    app.rules_wizard_status.borrow_mut().take();
}

fn selected_rules_wizard_rule_id(root: &AppRoot) -> Option<SmolStr> {
    let app = root.app.borrow();
    let rules = app.rules_wizard_rules.borrow();
    let cursor = app.rules_wizard_rule_cursor.get();
    rules
        .get(cursor.min(rules.len().saturating_sub(1)))
        .map(|rule| rule.id.clone())
}

fn clear_rules_wizard_delete_confirmation(root: &AppRoot) {
    let app = root.app.borrow();
    app.rules_wizard_delete_confirm.borrow_mut().take();
}

fn confirm_rules_wizard_delete_or_arm(root: &AppRoot, rule_id: &SmolStr) -> bool {
    let app = root.app.borrow();
    let mut pending = app.rules_wizard_delete_confirm.borrow_mut();
    if pending
        .as_ref()
        .is_some_and(|pending_id| pending_id.as_str() == rule_id.as_str())
    {
        pending.take();
        true
    } else {
        pending.replace(rule_id.clone());
        app.rules_wizard_status
            .borrow_mut()
            .replace(SmolStr::new(format!(
                "Press Delete again to permanently remove rule {rule_id}"
            )));
        false
    }
}

fn select_rules_wizard_rule(root: &AppRoot, index: usize) {
    let app = root.app.borrow();
    app.rules_wizard_delete_confirm.borrow_mut().take();
    let len = app.rules_wizard_rules.borrow().len();
    if index >= len {
        app.rules_wizard_rule_cursor.set(0);
        app.rules_wizard_status
            .borrow_mut()
            .replace(SmolStr::new_static("No persisted rule at clicked row"));
        return;
    }
    app.rules_wizard_rule_cursor.set(index);
    app.rules_wizard.borrow_mut().set_error(None);
    app.rules_wizard_status
        .borrow_mut()
        .replace(SmolStr::new(format!("Selected rule {}", index + 1)));
}

fn select_prev_rules_wizard_rule(root: &AppRoot) {
    let app = root.app.borrow();
    app.rules_wizard_delete_confirm.borrow_mut().take();
    let len = app.rules_wizard_rules.borrow().len();
    if len == 0 {
        app.rules_wizard_rule_cursor.set(0);
        app.rules_wizard_status
            .borrow_mut()
            .replace(SmolStr::new_static("No persisted rules to select"));
        return;
    }
    let cursor = app.rules_wizard_rule_cursor.get().saturating_sub(1);
    app.rules_wizard_rule_cursor.set(cursor);
    app.rules_wizard_status
        .borrow_mut()
        .replace(SmolStr::new(format!("Selected rule {}", cursor + 1)));
}

fn select_next_rules_wizard_rule(root: &AppRoot) {
    let app = root.app.borrow();
    app.rules_wizard_delete_confirm.borrow_mut().take();
    let len = app.rules_wizard_rules.borrow().len();
    if len == 0 {
        app.rules_wizard_rule_cursor.set(0);
        app.rules_wizard_status
            .borrow_mut()
            .replace(SmolStr::new_static("No persisted rules to select"));
        return;
    }
    let cursor = (app.rules_wizard_rule_cursor.get() + 1).min(len - 1);
    app.rules_wizard_rule_cursor.set(cursor);
    app.rules_wizard_status
        .borrow_mut()
        .replace(SmolStr::new(format!("Selected rule {}", cursor + 1)));
}

fn load_selected_rules_wizard_rule(root: &AppRoot) {
    let app = root.app.borrow();
    app.rules_wizard_delete_confirm.borrow_mut().take();
    let rules = app.rules_wizard_rules.borrow();
    let cursor = app.rules_wizard_rule_cursor.get();
    let Some(rule) = rules
        .get(cursor.min(rules.len().saturating_sub(1)))
        .cloned()
    else {
        drop(rules);
        app.rules_wizard
            .borrow_mut()
            .set_error(Some(SmolStr::new_static("No persisted rule selected")));
        app.rules_wizard_status.borrow_mut().take();
        return;
    };
    let name = rule.name.clone();
    drop(rules);
    app.rules_wizard.borrow_mut().load_rule(rule);
    app.rules_wizard_status
        .borrow_mut()
        .replace(SmolStr::new(format!("Editing rule '{name}'")));
}

fn drain_rules_wizard_action(root: &AppRoot, hwnd: HWND) {
    let action = {
        let app = root.app.borrow();
        app.rules_wizard.borrow_mut().take_action()
    };
    match action {
        Some(RulesWizardAction::Save(rule)) => {
            root.dispatcher.push(Command::SaveRule(rule));
        }
        Some(RulesWizardAction::PreviewRequest(rule)) => {
            root.dispatcher.push(Command::PreviewRuleHits(rule));
        }
        Some(RulesWizardAction::Cancel) => unsafe {
            ShowWindow(hwnd, SW_HIDE);
        },
        None => {}
    }
}

fn first_desktop_source_for_rules_preview() -> Result<PathBuf, RulesWizardError> {
    bento_nano_backend::desktop_sources::all_desktop_dirs(None)
        .into_iter()
        .next()
        .ok_or(RulesWizardError::NoDesktopSource)
}

fn preview_rule_for_wizard(root: &AppRoot, rule: &Rule) -> Result<usize, RulesWizardError> {
    let desktop = first_desktop_source_for_rules_preview()?;
    let desktop_string = desktop.to_string_lossy().to_string();
    let preview_zones = {
        let app = root.app.borrow();
        rules_preview_zones_from_app(&app)
    };
    let hits = rule_executor::preview(rule, &desktop_string, &preview_zones)
        .map_err(|error| RulesWizardError::Preview(error.to_string()))?;
    let count = hits.len();
    let app = root.app.borrow();
    let mut wizard = app.rules_wizard.borrow_mut();
    wizard.set_preview_hits(hits);
    wizard.set_error(None);
    drop(wizard);
    app.rules_wizard_status
        .borrow_mut()
        .replace(SmolStr::new(format!(
            "Preview matched {count} desktop files"
        )));
    Ok(count)
}

fn run_rule_now_for_wizard(
    root: &AppRoot,
    rule_id: &SmolStr,
) -> Result<ExecutionReport, RulesWizardError> {
    let state_dir = current_rules_state_dir(root)?;
    let rule = rules::load_all(&state_dir)
        .into_iter()
        .find(|rule| rule.id == *rule_id)
        .ok_or_else(|| RulesWizardError::RuleNotFound(rule_id.clone()))?;
    let desktop = first_desktop_source_for_rules_preview()?;
    let desktop_string = desktop.to_string_lossy().to_string();
    let preview_zones = {
        let app = root.app.borrow();
        rules_preview_zones_from_app(&app)
    };
    let plan = rule_executor::build_plan(&rule, &desktop_string, &preview_zones, None)
        .map_err(|error| RulesWizardError::Execution(error.to_string()))?;
    let before_snapshot = capture_current_timeline_snapshot(root, "before rule run");
    let report = apply_rules_execution_plan(root, &plan);
    record_rule_execution_timeline_pair(root, before_snapshot, &report);
    if report.matched > 0 {
        persist_rule_run_stats(&state_dir, rule.id.as_str())?;
    }
    let count = refresh_rules_wizard(root)?;
    let updated_rule = {
        let app = root.app.borrow();
        app.rules_wizard_rules
            .borrow()
            .iter()
            .find(|candidate| candidate.id == rule.id)
            .cloned()
    };
    let app = root.app.borrow();
    if let Some(updated_rule) = updated_rule {
        app.rules_wizard.borrow_mut().load_rule(updated_rule);
    }
    app.rules_wizard.borrow_mut().set_error(None);
    app.rules_wizard_status
        .borrow_mut()
        .replace(rules_execution_status(&report, count));
    Ok(report)
}

#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
struct FileChangeRulesOutcome {
    eligible_rules: usize,
    triggered_rules: usize,
    matched_files: usize,
    action_count: usize,
    error_count: usize,
}

impl FileChangeRulesOutcome {
    fn has_visible_status(self) -> bool {
        self.eligible_rules > 0
    }

    fn applied_actions(self) -> bool {
        self.triggered_rules > 0 || self.action_count > 0 || self.error_count > 0
    }
}

fn is_rules_file_change_event(event: &bento_nano_backend::watcher::FileChangedEvent) -> bool {
    matches!(event.event_type.as_str(), "create" | "modify")
}

fn rules_event_desktop_source(
    event: &bento_nano_backend::watcher::FileChangedEvent,
) -> Result<PathBuf, RulesWizardError> {
    Path::new(&event.path)
        .parent()
        .filter(|path| !path.as_os_str().is_empty())
        .map(Path::to_path_buf)
        .ok_or(RulesWizardError::NoDesktopSource)
}

fn normalized_rules_path(path: &str) -> String {
    let mut normalized = path.replace('\\', "/");
    while normalized.ends_with('/') && normalized.len() > 1 {
        normalized.pop();
    }
    normalized.to_ascii_lowercase()
}

fn file_change_path_matches(
    event: &bento_nano_backend::watcher::FileChangedEvent,
    candidate_path: &str,
) -> bool {
    normalized_rules_path(candidate_path) == normalized_rules_path(&event.path)
}

fn filter_file_change_files(
    event: &bento_nano_backend::watcher::FileChangedEvent,
    files: &[bento_nano_backend::grouping::scanner::FileInfo],
) -> Vec<bento_nano_backend::grouping::scanner::FileInfo> {
    files
        .iter()
        .filter(|file| file_change_path_matches(event, &file.path))
        .cloned()
        .collect()
}

fn filter_file_change_execution_plan(
    plan: &ExecutionPlan,
    event: &bento_nano_backend::watcher::FileChangedEvent,
) -> Option<ExecutionPlan> {
    let matched = filter_file_change_files(event, &plan.matched);
    if matched.is_empty() {
        return None;
    }

    let mut effects = Vec::new();
    for effect in &plan.effects {
        match effect {
            ActionEffect::MoveToZone { zone_id, files } => {
                let files = filter_file_change_files(event, files);
                if !files.is_empty() {
                    effects.push(ActionEffect::MoveToZone {
                        zone_id: zone_id.clone(),
                        files,
                    });
                }
            }
            ActionEffect::MoveToFolder { folder, files } => {
                let files = filter_file_change_files(event, files);
                if !files.is_empty() {
                    effects.push(ActionEffect::MoveToFolder {
                        folder: folder.clone(),
                        files,
                    });
                }
            }
            ActionEffect::DeleteToRecycleBin { files } => {
                let files = filter_file_change_files(event, files);
                if !files.is_empty() {
                    effects.push(ActionEffect::DeleteToRecycleBin { files });
                }
            }
            ActionEffect::Tag { tags, files } => {
                let files = filter_file_change_files(event, files);
                if !files.is_empty() {
                    effects.push(ActionEffect::Tag {
                        tags: tags.clone(),
                        files,
                    });
                }
            }
            ActionEffect::Notify { message } => {
                effects.push(ActionEffect::Notify {
                    message: message.clone(),
                });
            }
        }
    }

    Some(ExecutionPlan {
        rule_id: plan.rule_id.clone(),
        matched,
        effects,
    })
}

fn file_change_rules_status(
    event: &bento_nano_backend::watcher::FileChangedEvent,
    outcome: FileChangeRulesOutcome,
    persisted_count: usize,
) -> SmolStr {
    SmolStr::new(format!(
        "File change {} ran {}/{} OnFileChange rules; matched {}; actions={}; errors={}; persisted rules={persisted_count}; path={}",
        event.event_type,
        outcome.triggered_rules,
        outcome.eligible_rules,
        outcome.matched_files,
        outcome.action_count,
        outcome.error_count,
        event.path
    ))
}

fn refresh_file_change_rules_status(
    root: &AppRoot,
    event: &bento_nano_backend::watcher::FileChangedEvent,
    outcome: FileChangeRulesOutcome,
) -> Result<(), RulesWizardError> {
    if !outcome.has_visible_status() {
        return Ok(());
    }
    let count = refresh_rules_wizard(root)?;
    let app = root.app.borrow();
    app.rules_wizard_status
        .borrow_mut()
        .replace(file_change_rules_status(event, outcome, count));
    Ok(())
}

fn run_on_file_change_rules(
    root: &AppRoot,
    event: &bento_nano_backend::watcher::FileChangedEvent,
) -> Result<FileChangeRulesOutcome, RulesWizardError> {
    let state_dir = current_rules_state_dir(root)?;
    let mut outcome = FileChangeRulesOutcome::default();
    if !is_rules_file_change_event(event) {
        return Ok(outcome);
    }

    let rules = rules::load_all(&state_dir);
    let desktop = rules_event_desktop_source(event)?;
    let desktop_string = desktop.to_string_lossy().to_string();

    for rule in rules
        .into_iter()
        .filter(|rule| rule.enabled && matches!(&rule.run_mode, rules::RunMode::OnFileChange))
    {
        outcome.eligible_rules = outcome.eligible_rules.saturating_add(1);
        let preview_zones = {
            let app = root.app.borrow();
            rules_preview_zones_from_app(&app)
        };
        let plan = rule_executor::build_plan(&rule, &desktop_string, &preview_zones, None)
            .map_err(|error| RulesWizardError::Execution(error.to_string()))?;
        let Some(plan) = filter_file_change_execution_plan(&plan, event) else {
            continue;
        };

        let before_snapshot = capture_current_timeline_snapshot(root, "before file-change rule");
        let mut report = apply_rules_execution_plan(root, &plan);
        report.checkpoint_trigger = SmolStr::new_static("rule_file_change_applied");
        record_rule_execution_timeline_pair(root, before_snapshot, &report);
        if report.matched > 0 {
            persist_rule_run_stats(&state_dir, rule.id.as_str())?;
        }

        outcome.triggered_rules = outcome.triggered_rules.saturating_add(1);
        outcome.matched_files = outcome.matched_files.saturating_add(report.matched);
        outcome.action_count = outcome
            .action_count
            .saturating_add(report.actions_taken.len());
        outcome.error_count = outcome.error_count.saturating_add(report.errors.len());
        tracing::info!(
            target: "bentodesk::rules",
            rule_id = %rule.id,
            event_type = %event.event_type,
            path = %event.path,
            matched = report.matched,
            actions = report.actions_taken.len(),
            errors = report.errors.len(),
            "OnFileChange rule applied from desktop watcher event"
        );
    }

    refresh_file_change_rules_status(root, event, outcome)?;
    Ok(outcome)
}

#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
struct ScheduledRulesOutcome {
    eligible_rules: usize,
    triggered_rules: usize,
    matched_files: usize,
    action_count: usize,
    error_count: usize,
}

impl ScheduledRulesOutcome {
    fn has_visible_status(self) -> bool {
        self.eligible_rules > 0
    }

    fn applied_actions(self) -> bool {
        self.triggered_rules > 0 || self.action_count > 0 || self.error_count > 0
    }
}

fn interval_rules_status(
    rule_id: &SmolStr,
    outcome: ScheduledRulesOutcome,
    persisted_count: usize,
) -> SmolStr {
    SmolStr::new(format!(
        "Interval scheduler ran {}/{} Interval rules; matched {}; actions={}; errors={}; persisted rules={persisted_count}; rule={rule_id}",
        outcome.triggered_rules,
        outcome.eligible_rules,
        outcome.matched_files,
        outcome.action_count,
        outcome.error_count
    ))
}

fn refresh_interval_rules_status(
    root: &AppRoot,
    rule_id: &SmolStr,
    outcome: ScheduledRulesOutcome,
) -> Result<(), RulesWizardError> {
    if !outcome.has_visible_status() {
        return Ok(());
    }
    let count = refresh_rules_wizard(root)?;
    let app = root.app.borrow();
    app.rules_wizard_status
        .borrow_mut()
        .replace(interval_rules_status(rule_id, outcome, count));
    Ok(())
}

fn current_unix_secs_for_rules_scheduler() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_secs() as i64)
        .unwrap_or(0)
}

fn run_interval_rule_for_scheduler_event(
    root: &AppRoot,
    event: &SchedulerEvent,
) -> Result<ScheduledRulesOutcome, RulesWizardError> {
    let desktop = first_desktop_source_for_rules_preview()?;
    run_interval_rule_for_scheduler_event_with_desktop(root, event, &desktop)
}

fn run_interval_rule_for_scheduler_event_with_desktop(
    root: &AppRoot,
    event: &SchedulerEvent,
    desktop: &Path,
) -> Result<ScheduledRulesOutcome, RulesWizardError> {
    let SchedulerEvent::RuleDue { rule_id } = event;
    let state_dir = current_rules_state_dir(root)?;
    let Some(rule) = rules::load_all(&state_dir)
        .into_iter()
        .find(|rule| rule.id == *rule_id)
    else {
        tracing::debug!(
            target: "bentodesk::rules",
            rule_id = %rule_id,
            "rules scheduler event ignored because persisted rule no longer exists"
        );
        return Ok(ScheduledRulesOutcome::default());
    };

    let mut outcome = ScheduledRulesOutcome::default();
    if !rule.enabled || !matches!(&rule.run_mode, rules::RunMode::Interval { .. }) {
        tracing::debug!(
            target: "bentodesk::rules",
            rule_id = %rule.id,
            "rules scheduler event ignored because rule is disabled or no longer Interval"
        );
        return Ok(outcome);
    }
    if !rule_executor::should_run_now(&rule, current_unix_secs_for_rules_scheduler()) {
        tracing::debug!(
            target: "bentodesk::rules",
            rule_id = %rule.id,
            "rules scheduler event ignored because rule is no longer due"
        );
        return Ok(outcome);
    }

    outcome.eligible_rules = 1;
    let desktop_string = desktop.to_string_lossy().to_string();
    let preview_zones = {
        let app = root.app.borrow();
        rules_preview_zones_from_app(&app)
    };
    let plan = rule_executor::build_plan(&rule, &desktop_string, &preview_zones, None)
        .map_err(|error| RulesWizardError::Execution(error.to_string()))?;
    let before_snapshot = capture_current_timeline_snapshot(root, "before interval rule");
    let mut report = apply_rules_execution_plan(root, &plan);
    report.checkpoint_trigger = SmolStr::new_static("rule_interval_applied");
    record_rule_execution_timeline_pair(root, before_snapshot, &report);
    if report.matched > 0 {
        persist_rule_run_stats(&state_dir, rule.id.as_str())?;
    }

    outcome.triggered_rules = 1;
    outcome.matched_files = report.matched;
    outcome.action_count = report.actions_taken.len();
    outcome.error_count = report.errors.len();
    refresh_interval_rules_status(root, rule_id, outcome)?;
    tracing::info!(
        target: "bentodesk::rules",
        rule_id = %rule.id,
        desktop = %desktop.display(),
        matched = report.matched,
        actions = report.actions_taken.len(),
        errors = report.errors.len(),
        "Interval rule applied from selected-stack rules scheduler event"
    );
    Ok(outcome)
}

fn persist_rule_run_stats(state_dir: &Path, rule_id: &str) -> Result<(), RulesWizardError> {
    let mut persisted = rules::load_all(state_dir);
    let Some(rule) = persisted
        .iter_mut()
        .find(|rule| rule.id.as_str() == rule_id)
    else {
        return Err(RulesWizardError::RuleNotFound(SmolStr::new(rule_id)));
    };
    rule.last_run = Some(SmolStr::new(bento_nano_backend::time::now_rfc3339()));
    rule.run_count = rule.run_count.saturating_add(1);
    rules::save_all(state_dir, &persisted)?;
    Ok(())
}

fn rules_execution_status(report: &ExecutionReport, persisted_count: usize) -> SmolStr {
    let action_count = report.actions_taken.len();
    let error_count = report.errors.len();
    SmolStr::new(format!(
        "Run matched {} files; actions={action_count}; errors={error_count}; persisted rules={persisted_count}",
        report.matched
    ))
}

fn apply_rules_execution_plan(root: &AppRoot, plan: &ExecutionPlan) -> ExecutionReport {
    let mut report = ExecutionReport {
        matched: plan.matched.len(),
        actions_taken: Vec::new(),
        errors: Vec::new(),
        checkpoint_trigger: SmolStr::new_static("rule_applied"),
        checkpoint_key: Some(plan.rule_id.clone()),
    };

    for effect in &plan.effects {
        let description = match effect {
            ActionEffect::MoveToZone { zone_id, files } => {
                apply_rules_move_to_zone(root, zone_id, files, &mut report.errors)
            }
            ActionEffect::MoveToFolder { folder, files } => {
                apply_rules_move_to_folder(folder, files, &mut report.errors)
            }
            ActionEffect::DeleteToRecycleBin { files } => {
                apply_rules_delete(files, &mut report.errors)
            }
            ActionEffect::Tag { tags, files } => {
                apply_rules_tag(root, tags, files, &mut report.errors)
            }
            ActionEffect::Notify { message } => format!("Notified: {message}"),
        };
        if !description.is_empty() {
            report.actions_taken.push(description);
        }
    }
    report
}

fn rules_zone_id_from_wire(raw: &SmolStr) -> Option<ZoneId> {
    raw.as_str().trim().parse::<u64>().ok().map(ZoneId)
}

fn apply_rules_move_to_zone(
    root: &AppRoot,
    raw_zone_id: &SmolStr,
    files: &[bento_nano_backend::grouping::scanner::FileInfo],
    errors: &mut Vec<String>,
) -> String {
    let Some(zone_id) = rules_zone_id_from_wire(raw_zone_id) else {
        errors.push(format!("invalid MoveToZone target: {raw_zone_id}"));
        return "MoveToZone aborted".to_owned();
    };
    if root.app.borrow().zones.get(zone_id).is_none() {
        errors.push(format!("zone not found: {}", zone_id.0));
        return format!("Moved 0 file(s) to zone {}", zone_id.0);
    }
    if let Some(folder) = live_folder_path_for_zone(root, zone_id) {
        errors.push(format!(
            "zone {} is a read-only live folder mirror ({}); use MoveToFolder for filesystem moves",
            zone_id.0,
            folder.display()
        ));
        return format!("Moved 0 file(s) to live-folder zone {}", zone_id.0);
    }

    let mut added = 0usize;
    for file in files {
        if !Path::new(&file.path).exists() {
            errors.push(format!("source file no longer exists: {}", file.path));
            continue;
        }
        let item_path = bento_nano_app::ItemPath::new(file.path.clone());
        let icon_hash = load_icon_hash_for_path(&item_path).unwrap_or_default();
        let hidden = hide_item_file(root, zone_id, &file.path);
        let mut app = root.app.borrow_mut();
        if app
            .zones
            .add_item_with_metadata(
                zone_id,
                std::borrow::Cow::Owned(hidden.effective_path.clone()),
                Some(file.path.as_str()),
                std::borrow::Cow::Owned(icon_hash),
                hidden.original_path.map(std::borrow::Cow::Owned),
                hidden.hidden_path.map(std::borrow::Cow::Owned),
            )
            .is_some()
        {
            app.mark_dirty();
            added += 1;
        } else {
            errors.push(format!("failed to add {} to zone {}", file.path, zone_id.0));
        }
    }
    format!("Moved {added} file(s) to zone {}", zone_id.0)
}

fn apply_rules_move_to_folder(
    folder: &str,
    files: &[bento_nano_backend::grouping::scanner::FileInfo],
    errors: &mut Vec<String>,
) -> String {
    let destination = Path::new(folder);
    if let Err(error) = std::fs::create_dir_all(destination) {
        errors.push(format!("failed to create {folder}: {error}"));
        return "MoveToFolder aborted".to_owned();
    }

    let mut moved = 0usize;
    for file in files {
        let source = Path::new(&file.path);
        let Some(file_name) = source.file_name() else {
            errors.push(format!("invalid source path: {}", file.path));
            continue;
        };
        let target = destination.join(file_name);
        match std::fs::rename(source, &target) {
            Ok(()) => moved += 1,
            Err(error) => errors.push(format!(
                "rename {} -> {} failed: {error}",
                file.path,
                target.display()
            )),
        }
    }
    format!("Moved {moved} file(s) to folder {folder}")
}

fn tag_target_matches_item(file_path: &str, item: &bento_nano_zone::ZoneItem) -> bool {
    let target = normalized_rules_path(file_path);
    normalized_rules_path(item.path.as_ref()) == target
        || item
            .original_path
            .as_deref()
            .is_some_and(|path| normalized_rules_path(path) == target)
        || item
            .hidden_path
            .as_deref()
            .is_some_and(|path| normalized_rules_path(path) == target)
}

fn normalized_rule_tags(tags: &[SmolStr]) -> Vec<String> {
    let mut normalized = Vec::new();
    for tag in tags {
        let value = tag.as_str().trim();
        if value.is_empty() || normalized.iter().any(|existing| existing == value) {
            continue;
        }
        normalized.push(value.to_owned());
    }
    normalized
}

fn apply_rules_tag(
    root: &AppRoot,
    tags: &[SmolStr],
    files: &[bento_nano_backend::grouping::scanner::FileInfo],
    errors: &mut Vec<String>,
) -> String {
    let normalized_tags = normalized_rule_tags(tags);
    if normalized_tags.is_empty() {
        errors.push("Tag action has no non-empty tags".to_owned());
        return format!("Tagged 0 item(s) for {} file(s)", files.len());
    }

    let mut tagged_items = 0usize;
    let mut missing_items = 0usize;
    {
        let mut app = root.app.borrow_mut();
        for file in files {
            let mut matched_item = false;
            for zone in app.zones.iter_mut() {
                for item in &mut zone.items {
                    if !tag_target_matches_item(&file.path, item) {
                        continue;
                    }
                    matched_item = true;
                    let mut changed = false;
                    for tag in &normalized_tags {
                        if item.tags.iter().any(|existing| existing.as_ref() == tag) {
                            continue;
                        }
                        item.tags.push(Cow::Owned(tag.clone()));
                        changed = true;
                    }
                    if changed {
                        tagged_items = tagged_items.saturating_add(1);
                    }
                }
            }
            if !matched_item {
                missing_items = missing_items.saturating_add(1);
                errors.push(format!("no zone item found for tag target: {}", file.path));
            }
        }
        if tagged_items > 0 {
            app.mark_dirty();
        }
    }

    format!(
        "Tagged {tagged_items} item(s) for {} file(s) with {:?}; missing={missing_items}",
        files.len(),
        normalized_tags
    )
}

fn apply_rules_delete(
    files: &[bento_nano_backend::grouping::scanner::FileInfo],
    errors: &mut Vec<String>,
) -> String {
    let mut recycled = 0usize;
    for file in files {
        let path = Path::new(&file.path);
        if !path.exists() {
            errors.push(format!(
                "recycle delete {} failed: source missing",
                file.path
            ));
            continue;
        }
        match delete_path_to_recycle_bin(path) {
            Ok(RecycleDeleteOutcome::Recycled) => recycled += 1,
            Ok(RecycleDeleteOutcome::Aborted) => {
                errors.push(format!("recycle delete {} aborted by shell", file.path));
            }
            Err(error) => errors.push(format!("recycle delete {} failed: {error}", file.path)),
        }
    }
    format!("Recycled {recycled} file(s)")
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RecycleDeleteOutcome {
    Recycled,
    Aborted,
}

#[derive(Debug, Eq, PartialEq)]
enum FileOperationError {
    ShellDelete(i32),
}

impl core::fmt::Display for FileOperationError {
    fn fmt(&self, formatter: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        match self {
            Self::ShellDelete(code) => write!(formatter, "SHFileOperationW failed: {code}"),
        }
    }
}

impl core::error::Error for FileOperationError {}

fn shell_file_list_from_path(path: &Path) -> Vec<u16> {
    let mut file_list: Vec<u16> = path.as_os_str().encode_wide().collect();
    file_list.push(0);
    file_list.push(0);
    file_list
}

fn recycle_delete_flags() -> u16 {
    (FOF_ALLOWUNDO | FOF_WANTNUKEWARNING | FOF_NOERRORUI | FOF_SILENT) as u16
}

fn delete_path_to_recycle_bin(path: &Path) -> Result<RecycleDeleteOutcome, FileOperationError> {
    // SAFETY: `delete_path_to_recycle_bin_with` builds a valid SHFILEOPSTRUCTW
    // whose double-NUL file list lives for the duration of this synchronous
    // call; the Shell API only reads the struct while `SHFileOperationW` runs.
    delete_path_to_recycle_bin_with(path, |operation| unsafe {
        SHFileOperationW(operation as *mut SHFILEOPSTRUCTW)
    })
}

fn delete_path_to_recycle_bin_with<F>(
    path: &Path,
    mut file_operation: F,
) -> Result<RecycleDeleteOutcome, FileOperationError>
where
    F: FnMut(&mut SHFILEOPSTRUCTW) -> i32,
{
    let file_list = shell_file_list_from_path(path);
    let mut operation = SHFILEOPSTRUCTW {
        hwnd: ptr::null_mut(),
        wFunc: FO_DELETE,
        pFrom: file_list.as_ptr(),
        pTo: ptr::null(),
        fFlags: recycle_delete_flags(),
        fAnyOperationsAborted: 0,
        hNameMappings: ptr::null_mut(),
        lpszProgressTitle: ptr::null(),
    };
    let result = file_operation(&mut operation);
    if result != 0 {
        return Err(FileOperationError::ShellDelete(result));
    }
    if operation.fAnyOperationsAborted != 0 {
        return Ok(RecycleDeleteOutcome::Aborted);
    }
    Ok(RecycleDeleteOutcome::Recycled)
}

fn rules_preview_zones_from_app(app: &AppState) -> Vec<BentoZone> {
    bento_zones_from_app(app)
}

fn rules_item_type_for_path(path: &str) -> ItemType {
    let path_ref = Path::new(path);
    if path_ref.is_dir() {
        return ItemType::Folder;
    }
    match path_ref
        .extension()
        .and_then(|extension| extension.to_str())
        .unwrap_or_default()
    {
        "lnk" | "LNK" | "url" | "URL" => ItemType::Shortcut,
        "exe" | "EXE" | "msi" | "MSI" => ItemType::Application,
        _ => ItemType::File,
    }
}

fn rules_percent(value: i32, total: f32) -> f64 {
    if total <= 0.0 {
        return 0.0;
    }
    ((value.max(0) as f32 / total) * 100.0) as f64
}

