    fn scratch_zones_path(label: &str) -> std::path::PathBuf {
        let mut root = std::env::temp_dir();
        root.push(format!("bento-nano-capsule-{label}-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&root);
        root.join("zones.bin")
    }

