    // V-6 Round-2 (2026-05-21) — `toolbar_hover_point_for_event` retired
    // alongside `mount_main_tree`'s toolbar removal. The Main HWND tree no
    // longer mounts any IconButtons, so layout walks for a Main-tree
    // toolbar event id would fail. The downstream tooltip tests that used
    // this helper are retired below.
    #[allow(dead_code)]
    fn _retired_toolbar_hover_point_for_event_v6_r2(
        _app: &AppState,
        _win: &WindowState,
        _event_id: u32,
    ) -> (f32, f32) {
        (0.0, 0.0)
    }

    fn rect_center(rect: bento_nano_style::Rect) -> (f32, f32) {
        (rect.x + rect.width * 0.5, rect.y + rect.height * 0.5)
    }

    fn tooltip_checkpoint_meta(
        id: &'static str,
        summary: &'static str,
    ) -> bento_nano_backend::timeline::CheckpointMeta {
        bento_nano_backend::timeline::CheckpointMeta {
            id: SmolStr::new_static(id),
            captured_at: SmolStr::new_static("2026-05-12T00:00:00Z"),
            trigger: SmolStr::new_static("manual"),
            delta_summary: summary.to_owned(),
            pinned: false,
            zone_count: 2,
            item_count: 3,
        }
    }

    #[test]
    fn debug_overlay_toggle_command_flips_runtime_state() {
        let root = test_app_root();
        assert!(!root.app.borrow().debug_overlay.borrow().visible);

        root.dispatcher.push(Command::ToggleDebugOverlay);
        consume_dispatcher(&root, std::ptr::null_mut());
        assert!(root.app.borrow().debug_overlay.borrow().visible);

        root.dispatcher.push(Command::ToggleDebugOverlay);
        consume_dispatcher(&root, std::ptr::null_mut());
        assert!(!root.app.borrow().debug_overlay.borrow().visible);
    }

    #[test]
    fn about_commands_toggle_runtime_state_without_settings_placeholder() {
        let root = test_app_root();
        {
            let app = root.app.borrow();
            app.settings_open.set(true);
            assert!(!app.about_open.get());
        }

        root.dispatcher.push(Command::OpenAbout);
        consume_dispatcher(&root, std::ptr::null_mut());
        {
            let app = root.app.borrow();
            assert!(app.about_open.get());
            assert!(!app.settings_open.get());
        }

        root.dispatcher.push(Command::CloseAbout);
        consume_dispatcher(&root, std::ptr::null_mut());
        assert!(!root.app.borrow().about_open.get());
    }

