    fn tooltip_hover_search_row_producer_queues_show_and_hide() {
        let root = test_app_root();
        {
            let mut app = root.app.borrow_mut();
            app.viewport = Size {
                width: 640.0,
                height: 520.0,
            };
            let mut rows =
                smallvec::SmallVec::<[bento_nano_app::business::search_bar::SearchHit; 8]>::new();
            rows.push(bento_nano_app::business::search_bar::SearchHit {
                id: SmolStr::new_static("zone:77"),
                kind: bento_nano_backend::search::SearchItemKind::Zone,
                name: SmolStr::new_static("Contracts"),
                breadcrumb: SmolStr::new_static("Desktop / Work"),
                icon: SmolStr::new_static("grid"),
                score: 90,
                matched_token: SmolStr::new_static("contracts"),
            });
            app.search_bar.borrow_mut().set_results(rows);
        }
        let (row_x, row_y) = {
            let app = root.app.borrow();
            rect_center(bento_nano_app::business::search_bar::search_row_rect(
                app.viewport,
                0,
            ))
        };

        let show = {
            let app = root.app.borrow();
            tooltip_command_for_search_hover(&app, bento_nano_app::WindowHandle::NULL, row_x, row_y)
        };
        match show {
            Some(Command::ShowTooltip { anchor, text }) => {
                assert_eq!(anchor, bento_nano_app::WindowHandle::NULL);
                assert_eq!(text.as_str(), "Contracts - Desktop / Work");
            }
            other => panic!("expected search row tooltip, got {other:?}"),
        }

        {
            let app = root.app.borrow();
            assert!(app.show_tooltip_text(SmolStr::new_static("Contracts - Desktop / Work")));
        }
        let hide = {
            let app = root.app.borrow();
            tooltip_command_for_search_hover(&app, bento_nano_app::WindowHandle::NULL, 0.0, 0.0)
        };
        assert!(matches!(hide, Some(Command::HideTooltip)));
    }

