    fn file_change_event(event_type: &'static str, path: &std::path::Path) -> FileChangedEvent {
        FileChangedEvent {
            event_type: smol_str::SmolStr::new_static(event_type),
            path: path.to_string_lossy().to_string(),
            old_path: None,
        }
    }

